package registry

/*
expectedConstraints and expectedIndexes are pg_get_constraintdef and
pg_get_indexdef of every registry table as migration 00024 creates them
(conname contype own-table definition, sorted by name). A new migration
that changes a registry table must update them; checkCatalog fails on any
difference.
*/
var expectedConstraints = map[string]string{ // #nosec G101 -- constraint definitions, not credentials
	"registry_counter": "registry_counter_mac_check c true CHECK ((octet_length(mac) = 32)); registry_counter_pkey p true PRIMARY KEY (singleton); registry_counter_seq_check c true CHECK ((seq >= 0)); registry_counter_singleton_check c true CHECK (singleton)",
	"write_device":     "write_device_address_check c true CHECK ((masklen(address) =\nCASE family(address)\n    WHEN 4 THEN 32\n    ELSE 128\nEND)); write_device_device_id_check c true CHECK ((device_id > 0)); write_device_hostkey_algo_check c true CHECK ((hostkey_algo = ANY (ARRAY['ssh-rsa'::text, 'ecdsa-sha2-nistp256'::text, 'ecdsa-sha2-nistp384'::text, 'ecdsa-sha2-nistp521'::text, 'ssh-ed25519'::text]))); write_device_hostkey_fp_check c true CHECK ((hostkey_fp ~ '^SHA256:[A-Za-z0-9+/]{43}$'::text)); write_device_hostkey_pair c true CHECK (((hostkey_algo IS NULL) = (hostkey_fp IS NULL))); write_device_mac_check c true CHECK ((octet_length(mac) = 32)); write_device_pkey p true PRIMARY KEY (device_id); write_device_port_check c true CHECK (((port >= 1) AND (port <= 65535))); write_device_protocol_check c true CHECK ((protocol = 'ssh'::text)); write_device_version_check c true CHECK ((version > 0)); write_device_write_driver_check c true CHECK ((write_driver = ANY (ARRAY['mes6'::text, 'mes10'::text, 'esr'::text]))); write_device_write_group_check c true CHECK ((write_group ~ '^[a-z0-9][a-z0-9_.-]{0,63}$'::text)); write_device_writes_need_hostkey c true CHECK (((NOT writes_enabled) OR (hostkey_fp IS NOT NULL)))",
	"write_grant":      "write_grant_group_iff_write c true CHECK (((kind = 'write'::text) = (write_group IS NOT NULL))); write_grant_key u true UNIQUE NULLS NOT DISTINCT (user_id, kind, write_group); write_grant_kind_check c true CHECK ((kind = ANY (ARRAY['write'::text, 'write-admin'::text, 'unmask'::text, 'audit-read'::text]))); write_grant_mac_check c true CHECK ((octet_length(mac) = 32)); write_grant_user_id_check c true CHECK ((user_id > 0)); write_grant_username_snapshot_check c true CHECK (((char_length(username_snapshot) >= 1) AND (char_length(username_snapshot) <= 64))); write_grant_version_check c true CHECK ((version > 0)); write_grant_write_group_check c true CHECK ((write_group ~ '^[a-z0-9][a-z0-9_.-]{0,63}$'::text))",
	"change_totp":      "change_totp_ciphertext_check c true CHECK (((octet_length(ciphertext) >= 1) AND (octet_length(ciphertext) <= 1024))); change_totp_failures_check c true CHECK (((failures >= 0) AND (failures <= 1000000))); change_totp_key_version_check c true CHECK ((key_version > 0)); change_totp_last_step_check c true CHECK ((last_step >= 0)); change_totp_lock_count_check c true CHECK (((lock_count >= 0) AND (lock_count <= 1000000))); change_totp_mac_check c true CHECK ((octet_length(mac) = 32)); change_totp_pkey p true PRIMARY KEY (user_id); change_totp_user_id_check c true CHECK ((user_id > 0)); change_totp_username_snapshot_check c true CHECK (((char_length(username_snapshot) >= 1) AND (char_length(username_snapshot) <= 64))); change_totp_version_check c true CHECK ((version > 0))",
	"exec_state":       "exec_state_freeze_reason_check c true CHECK ((octet_length(freeze_reason) <= 1024)); exec_state_global_fail_window_check c true CHECK (((jsonb_typeof(global_fail_window) = ANY (ARRAY['array'::text, 'object'::text])) AND (octet_length((global_fail_window)::text) <= 65536))); exec_state_mac_check c true CHECK ((octet_length(mac) = 32)); exec_state_pkey p true PRIMARY KEY (singleton); exec_state_singleton_check c true CHECK (singleton); exec_state_version_check c true CHECK ((version > 0))",
	"model_profile":    "model_profile_firmware_re_check c true CHECK (((octet_length(firmware_re) >= 1) AND (octet_length(firmware_re) <= 256))); model_profile_id_check c true CHECK ((id > 0)); model_profile_mac_check c true CHECK ((octet_length(mac) = 32)); model_profile_model_re_check c true CHECK (((octet_length(model_re) >= 1) AND (octet_length(model_re) <= 256))); model_profile_note_check c true CHECK (((char_length(note) >= 1) AND (char_length(note) <= 1000))); model_profile_pkey p true PRIMARY KEY (id); model_profile_strategies_check c true CHECK (((jsonb_typeof(strategies) = 'object'::text) AND (octet_length((strategies)::text) <= 16384))); model_profile_version_check c true CHECK ((version > 0)); model_profile_write_driver_check c true CHECK ((write_driver = ANY (ARRAY['mes6'::text, 'mes10'::text, 'esr'::text])))",
	"write_credential": "write_credential_ciphertext_check c true CHECK (((octet_length(ciphertext) >= 1) AND (octet_length(ciphertext) <= 8240))); write_credential_device_id_check c true CHECK ((device_id > 0)); write_credential_kind_check c true CHECK ((kind = 'ssh_write'::text)); write_credential_mac_check c true CHECK ((octet_length(mac) = 32)); write_credential_nonce_check c true CHECK ((octet_length(nonce) = 16)); write_credential_pkey p true PRIMARY KEY (device_id); write_credential_version_check c true CHECK ((version > 0))",
}

var expectedIndexes = map[string]string{
	"registry_counter": "CREATE UNIQUE INDEX registry_counter_pkey ON exec.registry_counter USING btree (singleton)",
	"write_device":     "CREATE UNIQUE INDEX write_device_pkey ON exec.write_device USING btree (device_id)",
	"write_grant":      "CREATE UNIQUE INDEX write_grant_key ON exec.write_grant USING btree (user_id, kind, write_group) NULLS NOT DISTINCT",
	"change_totp":      "CREATE UNIQUE INDEX change_totp_pkey ON exec.change_totp USING btree (user_id)",
	"exec_state":       "CREATE UNIQUE INDEX exec_state_pkey ON exec.exec_state USING btree (singleton)",
	"model_profile":    "CREATE UNIQUE INDEX model_profile_pkey ON exec.model_profile USING btree (id)",
	"write_credential": "CREATE UNIQUE INDEX write_credential_pkey ON exec.write_credential USING btree (device_id)",
}
